import { ErrorBoundary } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { Suspense, useState } from 'react';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import i18n from '~/shared/i18n/i18n';
import { VoucherContent } from './voucher-content';

export const VoucherListPage = () => {
  useSetHeaderTitle(i18n.t('myVoucherStatus'));
  const [selectedAliasNm, setSelectedAliasNm] = useState('ALL');

  return (
    // 목록/빈 화면이 서로 다른 페이지 클래스를 쓰기 때문에 래퍼는 VoucherContent 가 렌더한다
    <QueryErrorResetBoundary>
      {({ reset }) => (
        <ErrorBoundary fallback={FallbackErrorMessage} onReset={reset} resetKeys={[selectedAliasNm]}>
          <Suspense fallback={<LoadingSpinner />}>
            <VoucherContent aliasNm={selectedAliasNm} />
          </Suspense>
        </ErrorBoundary>
      )}
    </QueryErrorResetBoundary>
  );
};
