import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useIssuedVoucherListInfiniteQuery } from '~/entities/voucher/api/hooks/use-issued-voucher-list-infinite-query';
import { VOUCHER_LIST_PAGING } from '~/entities/voucher/model/constants';
import { VoucherItem } from '~/entities/voucher/ui/voucher-item';
import { VoucherType } from '~/shared/api/dtos/enums';

type VoucherContentProps = {
  aliasNm: string;
};

export const VoucherContent = ({ aliasNm }: VoucherContentProps) => {
  const [ref, isContentVisible] = useInView();
  const { data: userRes } = useGetUserInfoQuery();
  const cstmrNo = userRes?.tbCstmrMastr?.cstmrNo ?? '';
  const userAliasNm = userRes?.tbCstmrMastr?.aliasNm ?? '';
  const {
    data: myVoucher,
    fetchNextPage,
    hasNextPage,
    isFetchingNextPage,
  } = useIssuedVoucherListInfiniteQuery({
    paging: {
      ...VOUCHER_LIST_PAGING,
      orderBy: {
        columnList: [
          { columnName: 'vouchProcSttusCd', sortDirection: 'ASC' },
          { columnName: 'rcvfverUseStartDt', sortDirection: 'DESC' },
          { columnName: 'vouchNm', sortDirection: 'DESC' },
        ],
        toSnakeCase: true,
      },
    },
    aliasNm,
    cstmrNo,
    userAliasNm,
  });

  const myVoucherList =
    myVoucher?.pages?.flatMap((page) => {
      const result = page?.result;
      if (aliasNm === 'ALL') {
        const walletItems = (result?.walletList ?? []).flatMap((w) => w.list ?? []);
        return walletItems.length > 0 ? walletItems : result?.list ?? [];
      }
      return result?.list ?? [];
    }) ?? [];

  useEffect(() => {
    if (hasNextPage && isContentVisible) fetchNextPage();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aliasNm, cstmrNo, userAliasNm, hasNextPage, isContentVisible]);

  // 빈 화면은 퍼블리싱(voucher_list_empty.html)이 공지 빈 화면 페이지 클래스를 쓴다
  if (myVoucherList.length === 0) {
    return (
      <div className="page-notice-empty-KBB KBB">
        <main>
          <section className="notice-empty-container">
            <i className="icon-empty-notice" aria-hidden="true"></i>
            <p className="empty-text">
              보유하고 계신
              <br />
              바우처가 없어요
            </p>
          </section>
        </main>
      </div>
    );
  }

  return (
    <div className="page-voucher-status-KBB KBB">
      <main>
        <section className="voucher-list-container">
          {myVoucherList.map((item, index) => (
            <VoucherItem
              key={item.vouchId ?? index}
              item={{ ...item, type: VoucherType.내_바우처 }}
              ref={index + 1 === myVoucherList.length ? ref : null}
            />
          ))}
        </section>
        {isFetchingNextPage && (
          <div className="common-pagination">
            <span className="page-dot"></span>
            <span className="page-dot"></span>
            <span className="page-dot"></span>
            <span className="page-dot"></span>
          </div>
        )}
      </main>
    </div>
  );
};
